<?php
include_once('../../inc/connection.php');
header('Content-Type: text/html; charset=utf-8');
if(($_POST['action']??'')!=='save_front_image'){echo '<div class="alert alert-danger">Invalid image action.</div>';exit;}
$allowed=['front_dashboard','kwedia_background','gwitia_background','kug_background','butchery_logo','butchery_background','app_icon'];$key=(string)($_POST['image_key']??'');
if(!in_array($key,$allowed,true)){echo '<div class="alert alert-danger">Invalid image slot.</div>';exit;}
$file=$_FILES['image_file']??null;if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){echo '<div class="alert alert-danger">Choose an image first.</div>';exit;}if((int)$file['size']>5*1024*1024){echo '<div class="alert alert-danger">The image must be 5 MB or smaller.</div>';exit;}
$ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));$mime=(string)($file['type']??'');if(!in_array($ext,['jpg','jpeg','png','webp','svg'],true)||!in_array($mime,['image/jpeg','image/png','image/webp','image/svg+xml'],true)){echo '<div class="alert alert-danger">Use JPG, PNG, WEBP, or SVG.</div>';exit;}
$dir=__DIR__.'/../../assets/img/front';if(!is_dir($dir)&&!mkdir($dir,0775,true)){echo '<div class="alert alert-danger">Could not create image folder.</div>';exit;}$name=$key.'_'.date('YmdHis').'_'.bin2hex(random_bytes(3)).'.'.$ext;$target=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$target)){echo '<div class="alert alert-danger">Could not store the image.</div>';exit;}
mysqli_query($connection,"CREATE TABLE IF NOT EXISTS kp_front_images (image_id INT NOT NULL AUTO_INCREMENT,image_key VARCHAR(60) NOT NULL,label VARCHAR(120) NOT NULL DEFAULT '',description VARCHAR(255) NOT NULL DEFAULT '',file_path VARCHAR(255) NOT NULL DEFAULT '',enabled TINYINT(1) NOT NULL DEFAULT 1,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(image_id),UNIQUE KEY uq_front_image_key(image_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$safeKey=mysqli_real_escape_string($connection,$key);$path=mysqli_real_escape_string($connection,'assets/img/front/'.$name);$enabled=!empty($_POST['enabled'])?1:0;mysqli_query($connection,"INSERT INTO kp_front_images(image_key,file_path,enabled) VALUES('$safeKey','$path','$enabled') ON DUPLICATE KEY UPDATE file_path=VALUES(file_path),enabled=VALUES(enabled)");
echo '<div class="alert alert-success"><strong>Saved.</strong> Front image updated successfully.</div>';
